package com.packsync.core;

import java.util.ArrayList;
import java.util.List;

/**
 * config/packsync-client.json — generated by the server on every publish and shipped
 * inside the pack, so players never edit it. It pins the update URL and the server's
 * public key: a client only ever accepts updates signed by THIS server.
 */
public final class PackClientConfig {
    public static final String PATH = "config/packsync-client.json";

    public String packName = "";
    public String manifestUrl = "";
    public List<String> mirrors = new ArrayList<>();
    public String publicKey = "";
    public String serverAddress = "";

    public boolean isUsable() {
        return manifestUrl != null && !manifestUrl.isBlank() && publicKey != null && !publicKey.isBlank();
    }

    /** Base URLs to try in order: the manifest's folder first, then mirrors. */
    public List<String> bases() {
        List<String> out = new ArrayList<>();
        if (manifestUrl != null && !manifestUrl.isBlank()) {
            String u = manifestUrl.trim();
            int q = u.indexOf('?');
            if (q >= 0) u = u.substring(0, q);
            if (u.endsWith("/manifest.json")) u = u.substring(0, u.length() - "/manifest.json".length());
            out.add(trimSlash(u));
        }
        if (mirrors != null) {
            for (String m : mirrors) {
                if (m != null && !m.isBlank() && !out.contains(trimSlash(m.trim()))) out.add(trimSlash(m.trim()));
            }
        }
        out.removeIf(u -> !(u.startsWith("http://") || u.startsWith("https://")));
        return out;
    }

    public static String trimSlash(String s) {
        while (s.endsWith("/")) s = s.substring(0, s.length() - 1);
        return s;
    }
}
